const { chromium } = require('playwright');

const PAGES = [
  'dashboard/billing',
  'dashboard/support',
  'dashboard/settings',
  'dashboard/team',
  'dashboard/partner',
  'dashboard/refer',
  'dashboard/activity',
  'dashboard/whats-new',
];

const VIEWPORTS = [
  { name: '1600', width: 1600, height: 1000 },
  { name: '1920', width: 1920, height: 1080 },
];

const THEMES = ['dark', 'light'];

(async () => {
  const browser = await chromium.launch();

  for (const theme of THEMES) {
    for (const vp of VIEWPORTS) {
      const context = await browser.newContext({
        viewport: { width: vp.width, height: vp.height },
        storageState: '/tmp/nxeon-audit-shots/state.json',
      });
      await context.addInitScript((t) => {
        try { localStorage.setItem('nx-theme', t); } catch (e) {}
      }, theme);

      for (const p of PAGES) {
        const page = await context.newPage();
        const consoleMsgs = [];
        page.on('console', (msg) => {
          if (msg.type() === 'error' || msg.type() === 'warning') {
            consoleMsgs.push(`[${msg.type()}] ${msg.text()}`);
          }
        });
        page.on('pageerror', (err) => {
          consoleMsgs.push(`[pageerror] ${err.message}`);
        });

        const slug = p.split('/').pop();
        try {
          await page.goto(`http://localhost:3021/${p}`, { waitUntil: 'networkidle', timeout: 20000 });
          await page.waitForTimeout(1200);
        } catch (e) {
          consoleMsgs.push(`[navigation error] ${e.message}`);
        }

        const fname = `/tmp/nxeon-audit-shots/${theme}-${vp.name}-${slug}.png`;
        try {
          await page.screenshot({ path: fname, fullPage: true });
        } catch (e) {
          consoleMsgs.push(`[screenshot error] ${e.message}`);
        }

        console.log(`\n=== ${theme} / ${vp.name} / ${p} ===`);
        console.log('URL:', page.url());
        if (consoleMsgs.length) {
          consoleMsgs.forEach((m) => console.log('  ' + m));
        } else {
          console.log('  (no console errors/warnings)');
        }
        await page.close();
      }
      await context.close();
    }
  }

  await browser.close();
})();

