import { getTicketThread, getTypingStatus, type TicketThread } from "@/lib/actions-support";
import ChatWidget, { type ChatViewer } from "@/components/ChatWidget";

type Ticket = {
  id: string; subject: string; status: string; priority: string;
  updated: string; preview: string; lastFromStaff: boolean;
};

type CompStatus = "operational" | "degraded" | "down";
type HealthComponent = "web" | "db" | "worker" | "proxmox";

type StatusData = {
  overall: CompStatus;
  components: { key: HealthComponent; label: string; status: CompStatus; uptimePct: number | null }[];
  incidents: { id: string; title: string; body: string; severity: "degraded" | "down" | "maintenance"; startedAt: string; resolvedAt: string | null }[];
};

type HelpSectionLite = { name: string; slug: string; emoji: string; blurb: string; count: number };

/* The real TicketStatus values, said in the customer's language. CUSTOMER_REPLY
   means they have answered and staff have not come back yet — "With support" is
   what that means to the person waiting, and it is the honest way round. */
/* `.badge`'s own tone variants (app/globals.css) swap the WHOLE gradient
   background, not just the text colour — badge-mint/-amber/-rose/-cyan each
   carry their own already-contrasting text colour baked in. Layering a bare
   `text-*` utility on top of the DEFAULT badge (a fixed blue-violet
   gradient) is what produced green/amber/cyan text sitting on a blue pill —
   the actual bug being fixed here. `tone: ""` deliberately means "the plain
   badge, no variant" for the two neutral/no-action-needed states, matching
   BillingView's identical StatusPill convention.
   ---
   Superseded by the light-not-shape tag study: no pill, no fill, no border —
   a small glowing dot with an off-axis bleed (the same directional glow
   language the sidebar's active row uses) and plain white text. `tone` here
   is one of nx-tag's real hue keys, not a `badge-*` class. `pulse` is set
   only on the states where something is actually waiting on an action —
   OPEN, ANSWERED and URGENT/HIGH — a breathing glow, not a hard blink,
   because several of these can be visible in one table at once. */
const STATUS: Record<string, { label: string; tone: string; pulse?: boolean }> = {
  OPEN:           { label: "Open",          tone: "amber", pulse: true },
  ANSWERED:       { label: "Reply waiting", tone: "cyan",  pulse: true },
  CUSTOMER_REPLY: { label: "With support",  tone: "slate" },
  CLOSED:         { label: "Closed",        tone: "mint" },
};

const PRIORITY: Record<string, { label: string; tone: string; pulse?: boolean }> = {
  LOW:    { label: "Low",    tone: "slate" },
  NORMAL: { label: "Normal", tone: "slate" },
  HIGH:   { label: "High",   tone: "amber", pulse: true },
  URGENT: { label: "Urgent", tone: "rose",  pulse: true },
