6	/**
7	 * Dark / light switch.
8	 *
9	 * Writes `data-theme` on <html> and remembers the choice in localStorage. The
10	 * FIRST paint is handled by an inline script in app/layout.tsx, not by this
11	 * component — a React effect runs after hydration, which is one paint too late
12	 * and shows a white flash on every load for anyone on light.
13	 *
14	 * Dark is the default and stays the product's identity; light is opt-in. The
15	 * rail and top bar are dark in both (see `.nx-dark-island` in globals.css), so
16	 * this control always sits on a dark surface and does not need to restyle
17	 * itself when the theme flips.
18	 */
19	
20	export const THEME_KEY = "nx-theme";
21	
22	export function ThemeToggle() {
23	  const [light, setLight] = useState(false);
24	
25	  /* Apply the stored preference on mount, then strip it on unmount.
26	   *
27	   * The inline script in app/layout.tsx only runs once, on the very first
28	   * document load — it never re-fires on a client-side route change, but
29	   * `<html>` is shared by the whole app (marketing and the dashboard render
30	   * inside the SAME root layout), so `data-theme` set here otherwise just
31	   * rides along on any soft navigation. This component only ever mounts
32	   * inside the dashboard shell, so its mount/unmount IS the "entered/left the
33	   * portal" signal: apply the saved choice when the customer lands here by
34	   * a client-side nav (the inline script had nothing to gate for this
35	   * specific route transition), and remove it the moment they navigate back
36	   * out, so marketing/login can never inherit a light theme they were never
37	   * built for — matching the inline script's own now-path-gated behavior.
38	   */
39	  useEffect(() => {
40	    let stored: string | null = null;
41	    try {
42	      stored = localStorage.getItem(THEME_KEY);
43	    } catch {
44	      /* Private mode or blocked storage — fail closed to dark. */
45	    }
46	    const isLight = stored === "light";
47	    setLight(isLight);
48	    const root = document.documentElement;
49	    if (isLight) root.setAttribute("data-theme", "light");
50	    return () => {
51	      root.removeAttribute("data-theme");
52	    };
53	  }, []);
54	
55	  function toggle() {
56	    const next = !light;
57	    setLight(next);
58	    const root = document.documentElement;
59	    if (next) root.setAttribute("data-theme", "light");
60	    else root.removeAttribute("data-theme");
61	    try {
62	      localStorage.setItem(THEME_KEY, next ? "light" : "dark");
63	    } catch {
64	      /* Private mode or blocked storage. The theme still applies for this
65	         session; it just will not be remembered, which is the right failure. */
66	    }
67	  }
