const { chromium } = require('playwright');
const OUT = '/tmp/nxeon-audit-shots';

(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({
    viewport: { width: 1600, height: 1000 },
    storageState: '/tmp/nxeon-audit-shots/state.json',
  });
  await context.addCookies([{
    name: 'nxeon_cookie_consent', value: 'all', domain: 'localhost', path: '/',
    expires: Math.floor(Date.now() / 1000) + 3600 * 24 * 365,
  }]);
  const page = await context.newPage();
  const consoleMsgs = [];
  page.on('console', (msg) => { if (msg.type() === 'error' || msg.type() === 'warning') consoleMsgs.push(`[console:${msg.type()}] ${msg.text()}`); });
  page.on('pageerror', (err) => consoleMsgs.push(`[pageerror] ${err.message}`));

  await page.goto('http://localhost:3021/dashboard/settings?tab=integrations#discord', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1000);
  console.log('URL after load:', page.url());
  const activeTab = await page.evaluate(() => {
    const active = document.querySelector('[class*="active"], [aria-current], .nx-tab-on');
    return active ? active.textContent : null;
  });
  console.log('Active tab text (best-effort):', activeTab);
  const scrollInfo = await page.evaluate(() => {
    const discordEl = document.getElementById('discord') || Array.from(document.querySelectorAll('*')).find(el => el.textContent?.trim() === 'Discord' && el.tagName !== 'SCRIPT');
    const rect = discordEl ? discordEl.getBoundingClientRect() : null;
    return {
      found: !!discordEl,
      inViewport: rect ? (rect.top >= 0 && rect.top < window.innerHeight) : null,
      rect,
      scrollY: window.scrollY,
    };
  });
  console.log('Discord element scroll info:', JSON.stringify(scrollInfo, null, 2));
  await page.screenshot({ path: `${OUT}/deeplink-settings-integrations-discord.png`, fullPage: true });

  console.log('\n=== console messages ===');
  consoleMsgs.forEach((m) => console.log(m));

  await browser.close();
})();

